return ['domain'=>'nitrosearch','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'it_IT','project-id-version'=>'NitroSearch for WooCommerce','pot-creation-date'=>'2026-08-01T09:52:15+00:00','po-revision-date'=>'2026-08-01 09:30+0000','messages'=>['NitroSearch for WooCommerce'=>'NitroSearch for WooCommerce','https://nitrosearch.io'=>'https://nitrosearch.io','Blazing-fast hosted search for WooCommerce. Syncs your catalog to NitroSearch and replaces the default WordPress search with instant, typo-tolerant results.'=>'Ricerca in cloud velocissima per WooCommerce. Sincronizza il catalogo con NitroSearch e sostituisce la ricerca predefinita di WordPress con risultati istantanei e tolleranti agli errori di battitura.','WebDeviant'=>'WebDeviant','https://webdeviant.io'=>'https://webdeviant.io','<strong>NitroSearch now measures how your store\'s search performs</strong> — anonymous, cookieless counts of searches and result clicks, with no shopper identifiers. It helps result ranking improve, and per-store reporting is on the roadmap.'=>'<strong>NitroSearch ora misura le prestazioni della ricerca del tuo negozio</strong> — conteggi anonimi e senza cookie delle ricerche e dei clic sui risultati, senza alcun identificatore dei clienti. Servono a migliorare l’ordinamento dei risultati, e i report per singolo negozio sono nella roadmap.','Manage it under %s.'=>'Puoi gestire questa impostazione da %s.','NitroSearch → Appearance'=>'NitroSearch → Design','Dismiss'=>'Ignora','Unauthorized.'=>'Non autorizzato.','Not connected'=>'Non collegato','Confirming control…'=>'Verifica del controllo…','Connected & verified'=>'Collegato e verificato','Amazon-quality search for WooCommerce'=>'Ricerca di livello Amazon per WooCommerce','Connect your store'=>'Collega il tuo negozio','Connect this store to NitroSearch to start syncing your catalogue and serving instant, typo-tolerant search. Nothing leaves your site until you click Connect.'=>'Collega questo negozio a NitroSearch per iniziare a sincronizzare il catalogo e offrire una ricerca istantanea e tollerante agli errori di battitura. Nulla lascia il tuo sito finché non fai clic su «Collega il negozio».','Provisioning token'=>'Token di provisioning','Optional. Only needed if you were given a token to connect this store.'=>'Facoltativo. Serve solo se ti è stato fornito un token per collegare questo negozio.','Connect store'=>'Collega il negozio','Confirming control of your site…'=>'Verifica del controllo del tuo sito…','We’re verifying that you control this store before building your search index. In production this is automatic; if your site isn’t reachable from our servers it can take a moment. Your catalogue syncs as soon as it’s confirmed.'=>'Stiamo verificando che questo negozio sia sotto il tuo controllo prima di costruire il tuo indice di ricerca. In produzione avviene in automatico; se il tuo sito non è raggiungibile dai nostri server, può volerci qualche istante. Il catalogo si sincronizza non appena la verifica è completata.','Check status'=>'Controlla lo stato','Disconnect'=>'Scollega','Dashboard'=>'Bacheca','Design'=>'Design','You’ve reached your plan’s limit.'=>'Hai raggiunto il limite del tuo piano.','Your search keeps running for everything already indexed, but new items won’t be added until you upgrade. Your products always take priority, so anything held back is a page or a post. Open %s below to move to a bigger plan.'=>'La ricerca continua a funzionare per tutto ciò che è già indicizzato, ma i nuovi elementi non verranno aggiunti finché non fai l’upgrade. I tuoi prodotti hanno sempre la priorità, quindi ciò che resta in attesa è una pagina o un articolo. Apri %s qui sotto per passare a un piano più grande.','Manage / Upgrade'=>'Gestisci / Fai l’upgrade','Sync health'=>'Stato della sincronizzazione','Search results indexed'=>'Risultati di ricerca indicizzati','Unlimited'=>'Senza limiti','Pending changes'=>'Modifiche in attesa','Last sync'=>'Ultima sincronizzazione','Never'=>'Mai','Last error'=>'Ultimo errore','Sync all products'=>'Sincronizza tutti i prodotti','Refresh status'=>'Aggiorna lo stato','%s from now'=>'tra %s','On demand'=>'Su richiesta','unit: millisecondsms'=>'ms','Sync performance'=>'Prestazioni di sincronizzazione','Avg sync speed'=>'Velocità media di sincronizzazione','Last batch'=>'Ultimo batch','Items synced'=>'Elementi sincronizzati','Batches sent'=>'Batch inviati','Next sync'=>'Prossima sincronizzazione','Changes to your catalogue are batched and pushed in the background — these figures show how quickly they reach your search index.'=>'Le modifiche al tuo catalogo vengono raggruppate e inviate in background — questi numeri mostrano quanto velocemente raggiungono il tuo indice di ricerca.','Search analytics'=>'Statistiche di ricerca','last 30 days'=>'ultimi 30 giorni','Couldn’t load analytics just now — it will retry automatically.'=>'Al momento non è stato possibile caricare le statistiche — riproveremo automaticamente.','<strong>%1$s</strong> on your store in the last 30 days. See what shoppers searched for, what they clicked, and what they looked for and didn’t find — included on every paid plan, from %2$s.'=>'<strong>%1$s</strong> sul tuo negozio negli ultimi 30 giorni. Scopri cosa hanno cercato i clienti, cosa hanno cliccato e cosa hanno cercato senza trovarlo — incluso in ogni piano a pagamento, a partire da %2$s.','%s search'=>'%s ricerca' . "\0" . '%s ricerche','%s/mo'=>'%s/mese','Upgrade to unlock'=>'Fai l’upgrade per sbloccare','Analytics starts collecting with plugin 1.5.0+ active — data appears within a few hours of shoppers searching.'=>'Le statistiche iniziano a essere raccolte con il plugin 1.5.0 o successivo attivo — i dati compaiono entro poche ore dalle ricerche dei clienti.','Searches'=>'Ricerche','Zero-result rate'=>'Percentuale senza risultati','Click-through'=>'Percentuale di clic','Top searches'=>'Ricerche più frequenti','Searched, found nothing'=>'Cercato, ma non trovato','View full analytics →'=>'Vedi le statistiche complete →','Your plan & account'=>'Il tuo piano e il tuo account','This store is claimed to a NitroSearch account. Manage your plan and billing from your NitroSearch dashboard.'=>'Questo negozio è associato a un account NitroSearch. Gestisci piano e fatturazione dalla dashboard del tuo account NitroSearch.','You\'re on the <strong>Free</strong> plan. Claim this store to a NitroSearch account to manage it or upgrade — your index and search stay exactly as they are.'=>'Sei sul piano <strong>Free</strong>. Associa questo negozio a un account NitroSearch per gestirlo o fare l’upgrade — il tuo indice e la tua ricerca restano esattamente come sono.','Roomy'=>'Spazioso','Two-line names and a clear picture. The default.'=>'Nomi su due righe e un’immagine ben visibile. L’impostazione predefinita.','Compact'=>'Compatto','Smaller rows, so more products fit before scrolling.'=>'Righe più piccole, così entrano più prodotti prima di scorrere.','Big pictures'=>'Immagini grandi','Larger thumbnails for image-led catalogues.'=>'Miniature più grandi per i cataloghi dove contano le immagini.','Text only'=>'Solo testo','No pictures — good for spares, parts and B2B.'=>'Niente immagini — ideale per ricambi, componenti e B2B.','Light'=>'Chiaro','A white panel. Suits most themes.'=>'Un pannello bianco. Adatto alla maggior parte dei temi.','Dark'=>'Scuro','A dark panel, for dark headers and themes.'=>'Un pannello scuro, per header e temi scuri.','Automatic'=>'Automatico','Follows each shopper\'s own device setting.'=>'Segue l’impostazione del dispositivo di ciascun cliente.','Custom'=>'Personalizzato','Choose your own panel and text colours below.'=>'Scegli qui sotto i colori del pannello e del testo.','Look'=>'Aspetto','Layout'=>'Layout','Products shown'=>'Prodotti mostrati','How many products appear in the drop-down as your shopper types.'=>'Quanti prodotti compaiono nel pannello dei risultati mentre il cliente digita.','Filters'=>'Filtri','Automatic (recommended)'=>'Automatico (consigliato)','Always across the top'=>'Sempre in alto','Hide in the drop-down'=>'Nascondi nel pannello dei risultati','In stock, on sale, brand and category filters. Automatic puts them in a side column when there is room, and across the top when there is not.'=>'Filtri per disponibilità, offerte, marchio e categoria. Con Automatico compaiono in una colonna laterale quando c’è spazio, e in alto quando non ce n’è.','Drop-down width'=>'Larghezza del pannello','Wide'=>'Ampio','Match my search box'=>'Come il campo di ricerca','Automatic gives product names enough room to read, even when your theme\'s search box is narrow. Match my search box keeps it exactly as wide as the box.'=>'Automatico dà ai nomi dei prodotti lo spazio per essere letti, anche quando il campo di ricerca del tuo tema è stretto. Come il campo di ricerca lo mantiene largo esattamente quanto il campo.','Colours'=>'Colori','Colour scheme'=>'Schema colori','Accent colour'=>'Colore d’accento','Used for prices, highlights and selected filters. Leave blank for the default. Text on top of it is set to black or white automatically, whichever stays readable.'=>'Usato per prezzi, elementi in evidenza e filtri selezionati. Lascia vuoto per usare il colore predefinito. Il testo sopra diventa automaticamente nero o bianco, a seconda di quale resta leggibile.','Panel background'=>'Sfondo del pannello','Only used when the colour scheme is set to Custom.'=>'Usato solo quando lo schema colori è impostato su Personalizzato.','Text colour'=>'Colore del testo','Corners'=>'Angoli','Rounded'=>'Arrotondati','Slightly rounded'=>'Leggermente arrotondati','Square'=>'Squadrati','Text style'=>'Stile del testo','Match my store'=>'Come il negozio','System default'=>'Predefinito di sistema','Custom font'=>'Font personalizzato','Match my store borrows the font your theme already uses around the search box.'=>'Come il negozio riprende il font che il tuo tema usa già attorno al campo di ricerca.','example font stacke.g. Georgia, serif'=>'es. Georgia, serif','Only used when Custom font is selected.'=>'Usato solo quando è selezionato Font personalizzato.','What to search'=>'Cosa cercare','Include'=>'Includi','Products'=>'Prodotti','always indexed'=>'sempre indicizzati','Pages'=>'Pagine','Blog posts'=>'Articoli del blog','Pages and posts count towards the same allowance as your products, so switching them off frees it up for your catalogue. Your products always come first and are never displaced by them. Private, password-protected and unpublished content is never indexed, and we honour %s set by Yoast SEO or Rank Math (per item, per content type, or site-wide).'=>'Pagine e articoli contano ai fini dello stesso limite dei tuoi prodotti: se li disattivi, liberi spazio per il tuo catalogo. I tuoi prodotti vengono sempre prima e non vengono mai scalzati da pagine o articoli. I contenuti privati, protetti da password o non pubblicati non vengono mai indicizzati, e rispettiamo il %s impostato con Yoast SEO o Rank Math (per singolo elemento, per tipo di contenuto o per l’intero sito).','Search results page'=>'Pagina dei risultati di ricerca','Enhance the product search results page with NitroSearch results and filters'=>'Potenzia la pagina dei risultati di ricerca dei prodotti con i risultati e i filtri di NitroSearch','Privacy &amp; credit'=>'Privacy e crediti','Search usage data'=>'Dati di utilizzo della ricerca','Share anonymous search usage counts with NitroSearch'=>'Condividi con NitroSearch conteggi anonimi di utilizzo della ricerca','Counts searches, result totals and result clicks on your store\'s search — cookieless and anonymous, with no shopper identifiers, no IP addresses and nothing stored in the shopper\'s browser. Used to improve result ranking and to power your search analytics. Untick to stop sending immediately.'=>'Conteggia le ricerche, i totali dei risultati e i clic sui risultati nella ricerca del tuo negozio — senza cookie e in forma anonima, senza identificatori dei clienti, senza indirizzi IP e senza salvare nulla nel browser del cliente. Questi dati servono a migliorare l’ordinamento dei risultati e ad alimentare le tue statistiche di ricerca. Togli la spunta per interrompere subito l’invio.','Powered-by credit'=>'Credito «Powered by»','Show a small “Powered by NitroSearch” credit, linking to nitrosearch.io'=>'Mostra un piccolo credito «Powered by NitroSearch» con link a nitrosearch.io','Off by default, and entirely your choice. Turning it on adds a small credit in the search box and one line in your site footer, both linking to %s — a normal, followed link. Nothing is added to your site unless you tick this. Thank you if you do.'=>'Disattivato per impostazione predefinita, e la scelta è solo tua. Attivandolo aggiungi un piccolo credito nel campo di ricerca e una riga nel footer del tuo sito, entrambi con link a %s — un link normale, follow. Nulla viene aggiunto al tuo sito se non metti la spunta. Grazie, se lo fai.','Advanced'=>'Avanzate','Search box selector'=>'Selettore del campo di ricerca','example CSS selectore.g. input.my-theme-search'=>'es. input.my-theme-search','Optional CSS selector for your theme\'s search input. Leave blank to auto-detect.'=>'Selettore CSS facoltativo per il campo di ricerca del tuo tema. Lascia vuoto per il rilevamento automatico.','Save design'=>'Salva il design','Connect failed: %s'=>'Collegamento non riuscito: %s','unknown error'=>'errore sconosciuto','Connected and verified.'=>'Collegato e verificato.','Connected. Confirming control of your site — this can take a moment. Use “Check status” below if it doesn’t update.'=>'Collegato. Stiamo verificando il controllo del tuo sito — può volerci qualche istante. Usa «Controlla lo stato» qui sotto se non si aggiorna.','Syncing %s product in the background, then your pages and posts.'=>'Stiamo sincronizzando %s prodotto in background, poi toccherà alle tue pagine e ai tuoi articoli.' . "\0" . 'Stiamo sincronizzando %s prodotti in background, poi toccherà alle tue pagine e ai tuoi articoli.','Syncing %s product in the background.'=>'Stiamo sincronizzando %s prodotto in background.' . "\0" . 'Stiamo sincronizzando %s prodotti in background.','Verified!'=>'Verificato!','%1$s search results indexed · %2$s pending.'=>'%1$s risultati di ricerca indicizzati · %2$s in attesa.','Still confirming control of your site — please try again in a moment.'=>'Stiamo ancora verificando il controllo del tuo sito — riprova tra qualche istante.','Design saved.'=>'Design salvato.','Saved. Removing your pages and blog posts from your index in the background.'=>'Salvato. Stiamo rimuovendo pagine e articoli del blog dal tuo indice in background.','Saved. Removing your pages from your index in the background.'=>'Salvato. Stiamo rimuovendo le pagine dal tuo indice in background.','Saved. Removing your blog posts from your index in the background.'=>'Salvato. Stiamo rimuovendo gli articoli del blog dal tuo indice in background.','Saved. Indexing your pages and blog posts in the background.'=>'Salvato. Stiamo indicizzando pagine e articoli del blog in background.','Saved. Indexing your pages in the background.'=>'Salvato. Stiamo indicizzando le pagine in background.','Saved. Indexing your blog posts in the background.'=>'Salvato. Stiamo indicizzando gli articoli del blog in background.','Disconnected.'=>'Scollegato.','This store is already claimed to a NitroSearch account.'=>'Questo negozio è già associato a un account NitroSearch.','We couldn’t confirm control of your site yet — click "Refresh status" first, then try again.'=>'Non siamo ancora riusciti a verificare il controllo del tuo sito — fai prima clic su «Aggiorna lo stato», poi riprova.','Your site needs re-checking — click "Refresh status", then try again.'=>'Il tuo sito deve essere ricontrollato — fai clic su «Aggiorna lo stato», poi riprova.','Too many attempts — please wait a minute and try again.'=>'Troppi tentativi — attendi un minuto e riprova.','Could not create a manage link. Please try again.'=>'Impossibile creare il link di gestione. Riprova.','Insufficient permissions.'=>'Permessi insufficienti.','Search powered by %s'=>'Ricerca fornita da %s','Refine results'=>'Affina i risultati','Refine'=>'Affina','In stock'=>'Disponibile','On sale'=>'In offerta','Brand'=>'Marchio','Category'=>'Categoria','View'=>'Vedi','Add to cart'=>'Aggiungi al carrello','Adding…'=>'Aggiunta in corso…','Added ✓'=>'Aggiunto ✓','Try again'=>'Riprova','Searching…'=>'Ricerca in corso…','Search is unavailable.'=>'La ricerca non è disponibile.','Search is unavailable right now.'=>'La ricerca non è disponibile in questo momento.','No products found.'=>'Nessun prodotto trovato.','No products found for “%s”.'=>'Nessun prodotto trovato per «%s».','Nothing found for “%s”.'=>'Nessun risultato per «%s».','Search products…'=>'Cerca prodotti…','Close search'=>'Chiudi la ricerca','Product results'=>'Risultati dei prodotti','Recent searches'=>'Ricerche recenti','Clear'=>'Cancella','Start typing to search products…'=>'Inizia a digitare per cercare i prodotti…','Sale'=>'In offerta','Out of stock'=>'Esaurito','Pages & posts'=>'Pagine e articoli','a website page, shown on a search resultPage'=>'Pagina','a blog post, shown on a search resultArticle'=>'Articolo','unit: milliseconds%s ms'=>'%s ms','Powered by %s'=>'Powered by %s','Page %1$s of %2$s'=>'Pagina %1$s di %2$s','← Prev'=>'← Precedente','Next →'=>'Successivo →','button labelSearch'=>'Cerca','%s product found.'=>'%s prodotto trovato.' . "\0" . '%s prodotti trovati.','See all %s result →'=>'Vedi %s risultato →' . "\0" . 'Vedi tutti i %s risultati →','%1$s result for “%2$s”'=>'%1$s risultato per «%2$s»' . "\0" . '%1$s risultati per «%2$s»','%s result'=>'%s risultato' . "\0" . '%s risultati']];